{
  "passages": [
    {
      "id": "m53",
      "about_topic": true,
      "says": "rule: wait for a smaller vehicle to move right before passing it when making a left turn"
    },
    {
      "id": "c6",
      "about_topic": true,
      "says": "rule: when making a left turn behind one of these vehicles, do not pull up beside it to make the turn at the same time"
    },
    {
      "id": "c7",
      "about_topic": true,
      "says": "rule: stay behind the vehicle and turn when the way is clear"
    },
    {
      "id": "m19",
      "about_topic": true,
      "says": "rule: left-turn lanes must not be used for passing"
    }
  ],
  "statements": [
    {
      "id": "s1",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Wait\")",
      "text": "a driver SHOULD NOT pass a [?smaller] vehicle WHEN the driver is making a left turn UNTIL the vehicle has moved right",
      "sources": [
        {
          "id": "m53",
          "quote": "Wait for the smaller vehicle to move right before you pass."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "smaller",
          "note": "No size threshold is given; the driver must judge which vehicle is smaller."
        }
      ],
      "links": [],
      "note": "The command to wait before passing is written as a SHOULD NOT rule with UNTIL."
    },
    {
      "id": "s2",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"do not\")",
      "text": "a driver SHOULD NOT pull up beside the vehicle to make the left turn at the same time WHEN the driver is making a left turn behind the vehicle AND the vehicle is one of [?these vehicles]",
      "sources": [
        {
          "id": "c6",
          "quote": "If you are making a left turn behind one of these vehicles, do not pull up beside it to make your turn at the same time."
        }
      ],
      "flags": [
        {
          "code": "R",
          "span": "these vehicles",
          "note": "The antecedent of 'these vehicles' is not supplied in this batch."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "s3",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Stay\")",
      "text": "a driver SHOULD stay behind the vehicle AND make the left turn WHEN the driver is making a left turn behind the vehicle AND the vehicle is one of [?these vehicles] AND the way is [?clear]",
      "sources": [
        {
          "id": "c6",
          "quote": "If you are making a left turn behind one of these vehicles, do not pull up beside it to make your turn at the same time."
        },
        {
          "id": "c7",
          "quote": "Stay behind and turn when the way is clear."
        }
      ],
      "flags": [
        {
          "code": "R",
          "span": "these vehicles",
          "note": "The antecedent of 'these vehicles' is not supplied in this batch."
        },
        {
          "code": "J",
          "span": "clear",
          "note": "No test for the way being clear is given."
        }
      ],
      "links": [],
      "note": "The condition about the vehicle is taken from the neighbouring passage c6."
    },
    {
      "id": "s4",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"not to be used\")",
      "text": "a driver MUST NOT use a left-turn lane to pass another vehicle",
      "sources": [
        {
          "id": "m19",
          "quote": "These left-turn lanes are not to be used for passing."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    }
  ]
}
